"""Create the auditable acceptance matrix without adding diagnostics to the product UI."""
from pathlib import Path
import json,gzip,csv,io,html
root=Path(__file__).resolve().parent.parent/'navigation-handover'
def read(name):
 p=root/name
 return json.loads(gzip.decompress(p.read_bytes()) if name.endswith('.gz') else p.read_text())
inv=read('after-audit-final.json.gz');hc=read('healthcare-audit.json.gz');sc=read('scenarios.json');pr=read('programmes.json');gate=read('build-gate.json')
rows=[]
for n,r in enumerate(inv['links'],1):
 c=r.get('contract') or {};dest=c.get('to') or c.get('external') or r.get('href') or r.get('onclick') or 'Tương tác tại trang'
 action=c.get('action','control');expected={'booking':'Biểu mẫu med-book, đúng đối tượng và đơn vị','programme':'Biểu mẫu med-program-register, đúng chương trình','partnership':'Liên hệ hợp tác, intent=partner và giữ nguồn','language':'Giữ trang/đối tượng, đổi ngôn ngữ','hotline':'tel đúng số đã cấu hình hoặc công bố chưa có','email':'mailto đúng địa chỉ của đơn vị','catalog':'Danh mục website hiện hữu','back':'Lịch sử truy cập','top':'Đầu trang hiện tại','bottom':'Cuối trang hiện tại'}.get(action,'Nội dung/điều khiển tương ứng với đích được khai báo')
 result='Đã kiểm kê và đối chiếu đích trong DOM'
 if c.get('status')=='unavailable':result='Đã phân biệt chức năng chưa kết nối';expected='Nêu rõ chưa kết nối, không giả lập hoàn tất'
 rows.append([r['site']+'/'+r['lang']+'/'+r['from'],c.get('object',r['from']),r.get('label') or r.get('id') or r.get('tag'),expected,str(dest),result,'','Điều hướng tập trung; đối chiếu route hiện có','Theo ma trận nghiệp vụ và kiểm thử hồi quy'])
for p in hc['pages']:
 for a in p['links']:
  c=a.get('contract') or {};dest=c.get('to') or c.get('external') or a.get('raw') or 'Thông báo tại trang'
  rows.append(['healthcare/'+p['lang']+'/'+p['page'],c.get('object',p['page']),a.get('label'),'Giữ đơn vị/đối tượng và ngữ cảnh của liên kết',str(dest),'Đã kiểm kê đích; không có đích thiếu','','Adapter Healthcare cùng hợp đồng','230 lượt trang/ngôn ngữ; kiểm tra trực tiếp các luồng đại diện'])
for suite in [sc,pr]:
 for c in suite['cases']:
  rows.append([c['name'],c['name'],c['name'],json.dumps(c.get('expected'),ensure_ascii=False),json.dumps(c.get('actual'),ensure_ascii=False),c['result'],c.get('error',''),'Kiểm thử thao tác DOM và khôi phục URL','PASS' if c['result']=='PASS' else 'FAIL'])
out=io.StringIO();w=csv.writer(out);w.writerow(['Trang xuất phát','Đối tượng','Tên nút/chức năng','Đích mong đợi','Đích thực tế','Kết quả','Lỗi','Biện pháp xử lý','Kết quả kiểm thử lại']);w.writerows(rows)
(root/'Ma_tran_kiem_thu.csv.gz').write_bytes(gzip.compress(('\ufeff'+out.getvalue()).encode(),mtime=0))
summary={'catalog_states':len(inv['pages']),'catalog_interactions':len(inv['links']),'catalog_structural_errors':len(inv['errors']),'healthcare_states':len(hc['pages']),'healthcare_links':sum(len(p['links']) for p in hc['pages']),'healthcare_structural_errors':len(hc['errors']),'business_assertions':len(sc['cases'])+len(pr['cases']),'business_failed':sc['failed']+pr['failed'],'matrix_rows':len(rows),'build_gate':gate}
(root/'SUMMARY.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2))
esc=html.escape
body=f'''<!doctype html><html lang="vi"><meta charset="utf-8"><title>Nghiệm thu điều hướng website TTH Group</title><style>body{{font-family:"Times New Roman",serif;font-size:14pt;line-height:1.45;max-width:1200px;margin:30px auto;padding:0 24px;color:#162840}}h1,h2{{font-size:14pt}}table{{border-collapse:collapse;width:100%;margin:16px 0}}th,td{{border:1px solid #aeb8c6;padding:9px;text-align:left;vertical-align:top}}img{{max-width:100%;height:auto}}.photos{{display:grid;grid-template-columns:1fr 1fr;gap:16px}}@media print{{body{{max-width:none;margin:0}}}}</style><h1>BÁO CÁO KIỂM THỬ ĐIỀU HƯỚNG WEBSITE TTH GROUP</h1><p>Ngày 28/11/2026. Nguồn tiếp quản: 9412d7ffaadd886a19deed520a914a05cd70a9b9. Giữ dự án, domain, kiến trúc thương hiệu và thiết kế đã duyệt.</p><table><tr><th>Phạm vi</th><th>Kết quả</th></tr><tr><td>Catalogue / Group / chuyên khoa / dưỡng lão</td><td>{summary['catalog_states']} lượt trang/ngôn ngữ; {summary['catalog_interactions']} thành phần tương tác; {summary['catalog_structural_errors']} đích thiếu</td></tr><tr><td>Healthcare và microsite</td><td>{summary['healthcare_states']} lượt trang/ngôn ngữ; {summary['healthcare_links']} liên kết; {summary['healthcare_structural_errors']} đích thiếu</td></tr><tr><td>Nghiệp vụ</td><td>{summary['business_assertions']} assertions thực hiện bằng trình duyệt; {summary['business_failed']} không đạt</td></tr><tr><td>Bảo vệ thiết kế</td><td>126 trang Healthcare và toàn bộ payload ảnh giữ nguyên; 70 script đã kiểm tra cú pháp. Hero desktop được đối chiếu ảnh trước–sau.</td></tr></table><p>Số thành phần trong kiểm kê không đồng nghĩa với số lượt click độc lập. Ma trận nghiệp vụ xác minh đích, đối tượng và các giá trị thực tế trong biểu mẫu; kiểm kê toàn trang xác minh sự tồn tại và ngữ cảnh của các đích được khai báo.</p><h2>Các lỗi đã xử lý</h2><p>Hotline sai hành vi; mất ý định hợp tác; mất đối tượng khi reload/đổi ngôn ngữ; xung đột menu cha; thiếu hồ sơ dịch vụ Nguyên Tâm; CTA bác sĩ/microsite Healthcare; nút VI | EN gộp; fragment/điều khiển chưa kết nối; điều hướng hồ sơ kiến trúc. Chi tiết: BUGS.md và NAVIGATION_CONTRACT.md.</p><h2>Phạm vi vận hành thực tế</h2><p>Đặt lịch và chương trình vẫn là biểu mẫu minh họa khi chưa kết nối HIS/CRM; không gửi hoặc xác nhận yêu cầu thật. Không tự gán hotline/OA chưa có dữ liệu. Nguồn Healthcare chưa có bản dịch EN đầy đủ cho mọi trang; điều hướng giữ ngữ cảnh và đánh dấu nội dung dịch chưa đầy đủ.</p><h2>Bằng chứng hero</h2><div class="photos"><div><p>Trước hiệu chỉnh</p><img src="evidence/hero-before.jpg"></div><div><p>Sau hiệu chỉnh</p><img src="evidence/hero-after.jpg"></div></div><h2>Tệp kiểm chứng và tiếp quản</h2><p>Ma_tran_kiem_thu.csv.gz chứa đủ chín trường yêu cầu. SUMMARY.json, build-gate.json, hero-comparison.json, scenarios.json, programmes.json và các báo cáo JSON nén là dữ liệu kiểm chứng. TAKEOVER.md mô tả cách khôi phục, build và chạy lại. Thông tin phát hành production được ghi trong hồ sơ sau deploy.</p></html>'''
(root/'Bao_cao_nghiem_thu.html').write_text(body)
print(json.dumps(summary,ensure_ascii=False))
